import dis, marshal

with open('flet_ui/__pycache__/site_settings_panel.cpython-312.pyc', 'rb') as f:
    f.read(16)
    code = marshal.load(f)

# Recursively dump all bytecode
def dump(c, depth=0):
    prefix = '  ' * depth
    print(f'{prefix}--- {c.co_name} ---')
    for instr in dis.get_instructions(c):
        if instr.opname == 'LOAD_ATTR':
            print(f'{prefix}LOAD_ATTR {instr.argval} L{instr.positions.lineno if instr.positions else \"?\"}')
    for const in c.co_consts:
        if isinstance(const, type(code)):
            dump(const, depth+1)

dump(code)
" 2>&1 | head -60", "note": "递归 dump 所有 code object 的 LOAD_ATTR"}
